@Service
public class PaymentService {
    private final String apiKey;
    private final int timeout;
    private final boolean featureEnabled;
    private final double calculatedRate;

    public PaymentService(
            @Value("${payment.api.key}") String apiKey,  // Property from application.properties
            @Value("${payment.timeout:5000}") int timeout,  // Default 5000 if not set
            @Value("${features.new-checkout:false}") boolean featureEnabled,  // Boolean property
            @Value("#{${payment.base.rate} * 1.15}") double calculatedRate) {  // SpEL expression
        this.apiKey = apiKey;
        this.timeout = timeout;
        this.featureEnabled = featureEnabled;
        this.calculatedRate = calculatedRate;
    }

    public void processPayment(Order order) {
        System.out.println("Using API key: " + apiKey.substring(0, 5) + "...");
        System.out.println("Timeout: " + timeout + "ms");
        if (featureEnabled) {
            System.out.println("New checkout flow with rate: " + calculatedRate);
        }
    }
}
