@Configuration
@PropertySource("classpath:database.properties")  // Loads custom file
@PropertySource(value = "classpath:optional-config.properties", ignoreResourceNotFound = true)  // Optional file
public class DatabaseConfig {

    @Value("${db.connection.pool.size}")
    private int poolSize;

    @Value("${db.connection.timeout:30}")
    private int timeout;

    @Bean
    public DataSource dataSource(
            @Value("${db.url}") String url,
            @Value("${db.username}") String username,
            @Value("${db.password}") String password) {
        var ds = new HikariDataSource();
        ds.setJdbcUrl(url);
        ds.setUsername(username);
        ds.setPassword(password);
        ds.setMaximumPoolSize(poolSize);
        ds.setConnectionTimeout(timeout * 1000L);
        return ds;
    }
}

// database.properties content:
// db.url=jdbc:postgresql://localhost:5432/mydb
// db.username=dbuser
// db.password=dbpass
// db.connection.pool.size=10
